// Constrói uma mensagem clara a partir dos dados do erro que o N8N
// fornece automaticamente ao Error Trigger.
const d = $json;
const nomeWorkflow = (d.workflow && d.workflow.name) || 'desconhecido';
const execId = d.execution && d.execution.id;
const execUrl = d.execution && d.execution.url;
const erroMsg = (d.execution && d.execution.error && d.execution.error.message) || 'sem detalhe';
const nodeErro = (d.execution && d.execution.error && d.execution.error.node && d.execution.error.node.name) || 'desconhecido';
const quando = new Date().toLocaleString('pt-PT', { timeZone: 'Europe/Lisbon' });

const textoWhatsapp = `🔴 *Workflow falhou*\n\n*${nomeWorkflow}*\nNó: ${nodeErro}\nErro: ${erroMsg.slice(0, 200)}\n\n${quando}` + (execUrl ? `\n👉 ${execUrl}` : '');

const html = '<div style="font-family:sans-serif;max-width:520px;">' +
  '<h2 style="color:#B4756A;">🔴 Workflow falhou</h2>' +
  '<p><strong>' + nomeWorkflow + '</strong></p>' +
  '<p>Nó: ' + nodeErro + '</p>' +
  '<p>Erro: ' + erroMsg.slice(0, 500) + '</p>' +
  '<p>Verificado em: ' + quando + '</p>' +
  (execUrl ? '<p><a href="' + execUrl + '">Ver execução no N8N</a></p>' : '') +
  '</div>';

return [{ json: { nomeWorkflow, erroMsg, textoWhatsapp, subject: '🔴 Workflow falhou — ' + nomeWorkflow, html } }];

